function botProfilePlan(
  request: BotProfileChangeRequest,
  digest = DIGEST,
  effect: "change" | "none" = "change",
): BotProfileChangePlan {
  const requestedFields = (["avatar", "banner", "username"] as const)
    .filter((field) => request[field] !== undefined)
  const current = {
    avatar: {
      animated: false,
      present: request.avatar?.action === "clear" && effect === "change",
    },
    banner: {
      animated: false,
      present: request.banner?.action === "clear" && effect === "change",
    },
    username: effect === "none" && request.username
      ? request.username
      : "current-bot",
  }
  const desiredImage = (
    field: "avatar" | "banner",
  ) => {
    const change = request[field]
    if (!change || effect === "none") return current[field]
    return change.action === "clear"
      ? { animated: false, present: false }
      : { animated: false, present: true }
  }
  const planFile = (field: "avatar" | "banner") => (
    request[field]?.action === "set"
      ? {
          contentDigest: `hmac-sha256:${(field === "avatar" ? "a" : "b").repeat(64)}`,
          review: {
            animated: false,
            containedByConfiguredRoot: true as const,
            durationSeconds: null,
            format: "png" as const,
            height: 128,
            mediaType: "image/png" as const,
            ownerMatchesProcess: true as const,
            regularFile: true as const,
            singleLink: true as const,
            sizeBytes: 128,
            stableRead: true as const,
            width: 128,
          },
        }
      : null
  )
  return {
    applicationId: APPLICATION_ID,
    botId: BOT_ID,
    changedFields: effect === "change" ? [...requestedFields] : [],
    createdAt: "2026-08-28T00:00:00.000Z",
    current,
    desired: {
      avatar: desiredImage("avatar"),
      banner: desiredImage("banner"),
      username: request.username ?? current.username,
    },
    digest,
    effect,
    files: {
      avatar: planFile("avatar"),
      banner: planFile("banner"),
    },
    operationKeyHash: operationKeyHash(request.operationKey),
    privacy: {
      omittedFields: [
        "application-payload",
        "avatar-hash",
        "banner-hash",
        "file-paths",
        "image-bytes",
        "raw-operation-key",
        "raw-user-payload",
      ],
      persistence: "content-free-records-only",
    },
    requestedFields: [...requestedFields],
    responseUnknownFieldCount: 0,
    reviewReason: request.reviewReason,
    risks: [
      "Application-wide presentation change",
      "External current-user race",
      "No Discord audit-log reason",
      "One-shot operation key",
    ],
    schemaVersion: 1,
    status: effect === "change" ? "planned" : "already-current",
    verification: {
      applicationIdentity: "exact",
      imageByteEquality: "not-observable",
      mutationResponse: "strict-current-bot-profile",
      readback: "independent-exact-editable-state",
    },
    warnings: [
      "Review reason is ephemeral",
      "Image readback does not prove byte equality",
    ],
    writeRequired: effect === "change",
  }
}

function applicationRoleConnectionMetadataPlan(
  request: ApplicationRoleConnectionMetadataChangeRequest,
  digest = DIGEST,
  effect: "change" | "none" = "change",
): ApplicationRoleConnectionMetadataPlan {
  const desired = request.action === "clear"
    ? []
    : structuredClone(request.records)
  const current = effect === "none"
    ? structuredClone(desired)
    : request.action === "clear"
      ? [structuredClone(APPLICATION_ROLE_CONNECTION_METADATA_RECORD)]
      : []
  return {
    acknowledgement: request.action === "clear"
      ? "complete-schema-clearance"
      : "application-wide-replacement",
    action: request.action,
    applicationId: APPLICATION_ID,
    botId: BOT_ID,
    createdAt: "2026-08-25T00:00:00.000Z",
    current,
    currentSchemaDigest: applicationRoleConnectionMetadataSchemaDigest(current),
    desired,
    desiredSchemaDigest: applicationRoleConnectionMetadataSchemaDigest(desired),
    diff: {
      added: effect === "change" && request.action === "replace" ? desired.length : 0,
      changed: 0,
      removed: effect === "change" && request.action === "clear" ? current.length : 0,
      reordered: false,
      unchanged: effect === "none" ? desired.length : 0,
    },
    digest,
    effect,
    operationKeyHash: operationKeyHash(request.operationKey),
    privacy: {
      definitionsPersisted: false,
      omitted: [
        "guild-role-configuration",
        "raw-discord-payloads",
        "user-role-connection-values",
        "verification-endpoint-url",
      ],
      text: "transient-untrusted",
    },
    risks: [
      "Application-wide complete-schema replacement",
      "Omitted criteria may invalidate guild role conditions",
      "No conditional update or audit-log reason",
      "One-shot operation key",
    ],
    schemaVersion: 1,
    status: effect === "change"
      ? "planned"
      : request.action === "clear" ? "already-empty" : "already-current",
    verification: {
      applicationIdentity: "exact",
      independentReadback: true,
      requestRetries: false,
      response: "exact-complete-schema",
    },
    verificationEndpointConfigured: true,
    warnings: [
      "Metadata labels and localization values are transient untrusted data",
      "Guild role configuration and user values are unavailable",
    ],
    writeRequired: effect === "change",
  }
}

