test("MCP Activity-instance inspection is exact-scope, count-only, and strict", async (context) => {
  const instanceId = "activity:instance%opaque"
  const { applicationActivityInstanceCalls, client } = await connectedFixture(context)

  const response = await client.callTool({
    arguments: {
      channelId: CHANNEL_ID,
      guildId: GUILD_ID,
      instanceId,
      userId: USER_ID,
    },
    name: "inspect_application_activity_instance",
  })
  const data = structuredContent(response)
  const invalidResults = await Promise.all([
    client.callTool({
      arguments: { channelId: CHANNEL_ID, guildId: GUILD_ID, instanceId: "unsafe/id" },
      name: "inspect_application_activity_instance",
    }),
    client.callTool({
      arguments: {
        channelId: CHANNEL_ID,
        guildId: GUILD_ID,
        instanceId,
        unexpected: true,
      },
      name: "inspect_application_activity_instance",
    }),
    client.callTool({
      arguments: {
        channelId: CHANNEL_ID,
        guildId: GUILD_ID,
        instanceId,
        userId: "0",
      },
      name: "inspect_application_activity_instance",
    }),
  ])

  assert.notEqual(response.isError, true)
  assert.equal(data.active, true)
  assert.equal(data.instanceId, instanceId)
  assert.equal(data.participantCount, 1)
  assert.deepEqual(data.expected, {
    channelId: CHANNEL_ID,
    guildId: GUILD_ID,
    user: { id: USER_ID, present: true },
  })
  assert.equal("userIds" in data, false)
  assert.doesNotMatch(JSON.stringify(response), new RegExp(OTHER_USER_ID, "u"))
  assert.equal(invalidResults.every((result) => result.isError === true), true)
  assert.equal(applicationActivityInstanceCalls.count, 1)
  assert.deepEqual(applicationActivityInstanceCalls.arguments?.[0], {
    channelId: CHANNEL_ID,
    guildId: GUILD_ID,
    instanceId,
    userId: USER_ID,
  })
  assert.equal(
    applicationActivityInstanceCalls.arguments?.[1]?.signal instanceof AbortSignal,
    true,
  )
  const tool = listedTool(
    (await client.listTools()).tools,
    "inspect_application_activity_instance",
  )
  assert.deepEqual(tool.annotations, {
    destructiveHint: false,
    idempotentHint: true,
    openWorldHint: true,
    readOnlyHint: true,
  })
  assert.match(tool.description || "", /participant enumeration/u)
  assert.match(tool.description || "", /nothing is persisted/u)
})

test("MCP status and safety resource disclose durable coordination boundaries", async (context) => {
  const { client } = await connectedFixture(context)

  const installationAudit = structuredContent(await client.callTool({
    arguments: {},
    name: "audit_bot_installations",
  }))

  const commands = structuredContent(await client.callTool({
    arguments: { guildId: GUILD_ID },
    name: "audit_application_commands",
  }))
  const posture = structuredContent(await client.callTool({
    arguments: {},
    name: "audit_application_posture",
  }))
  const linkedRoles = structuredContent(await client.callTool({
    arguments: {},
    name: "audit_application_role_connection_metadata",
  }))
  const applicationSkus = structuredContent(await client.callTool({
    arguments: {},
    name: "audit_application_skus",
  }))
  const status = structuredContent(await client.callTool({
    arguments: {},
    name: "get_connector_status",
  }))
  assert.deepEqual(status.application, {
    guildMembersIntent: "enabled",
    id: "500000000000000001",
    messageContentIntent: "enabled",
  })
  assert.deepEqual(status.bot, { id: "600000000000000001" })
  assert.deepEqual(status.installationAudit, installationAudit)
  assert.deepEqual(installationAudit.drift, {
    detected: false,
    missingConfiguredGuildIds: [],
    unexpectedGuildIds: [],
  })
  assert.deepEqual(installationAudit.privacy, BOT_INSTALLATION_AUDIT_PRIVACY)
  assert.deepEqual(status.privacy, CONNECTOR_STATUS_PRIVACY)
  assert.equal(status.schemaVersion, CONNECTOR_STATUS_SCHEMA_VERSION)
  assert.equal("auditFile" in status, false)
  assert.deepEqual(status.writeCoordination, {
    coverage: "receipt-backed-reviewed-writes",
    excludedWorkflows: ["ordinary-message-interactions"],
    localFilesystemRequired: true,
    mode: "durable-exact-target",
    resumableWorkflows: ["guild-scaffold"],
    sharedStateRootRequired: true,
  })
  assert.deepEqual(status.applicationPosture, posture)
  assert.deepEqual(commands.application, {
    botId: BOT_ID,
    id: APPLICATION_ID,
    installationTypes: {
      complete: true,
      reported: true,
      unknownValues: 0,
      values: ["guild-install"],
    },
  })
  assert.deepEqual(commands.inventory, {
    completeness: "complete-current-application",
    global: 1,
    guild: 0,
    permissions: 1,
    total: 1,
  })
  assert.equal((commands.guild as Record<string, unknown>).id, GUILD_ID)
  assert.deepEqual(posture.findingCounts, { blockers: 0, warnings: 0 })
  assert.equal(
    (posture.interactions as Record<string, unknown>).delivery,
    "gateway",
  )
  assert.doesNotMatch(JSON.stringify(posture), /https:\/\//u)
  assert.deepEqual(linkedRoles.application, {
    botId: BOT_ID,
    id: APPLICATION_ID,
    verificationEndpointConfigured: true,
  })
  assert.deepEqual(linkedRoles.inventory, {
    completeness: "complete-current-application",
    count: 1,
    documentedLimit: 5,
    projectionComplete: true,
  })
  assert.doesNotMatch(JSON.stringify(linkedRoles), new RegExp(TOKEN, "u"))
  assert.deepEqual(applicationSkus.application, {
    botId: BOT_ID,
    id: APPLICATION_ID,
  })
  assert.deepEqual(applicationSkus.inventory, {
    completeness: "complete-current-application",
    count: 1,
    documentedOwnerCreatedLimit: 50,
    localRecordLimit: 100,
    projectionComplete: true,
  })
  assert.doesNotMatch(JSON.stringify(applicationSkus), new RegExp(TOKEN, "u"))

  const resource = await client.readResource({ uri: MCP_RESOURCE_URIS.safety })
  const content = resource.contents[0]
  assert.ok(content && "text" in content)
  if (!content || !("text" in content)) throw new Error("Expected safety text")
  assert.match(content.text, /durable exact target claims/)
  assert.match(content.text, /member moderation claims its exact member and the guild member collection/iu)
  assert.match(content.text, /Resumable guild scaffolds claim both guild role and channel collections/)
  assert.match(content.text, /interruption with pending evidence leaves them quarantined/)
  assert.match(content.text, /complete obfuscation-safe Gateway layout/)
  assert.match(content.text, /one non-retried complete position PATCH/)
  assert.match(content.text, /newer complete matching Gateway layout/)
  assert.match(content.text, /Exact-reference parsing converts one complete canonical Discord/)
  assert.match(content.text, /never scans prose, resolves names, contacts Discord/)
  assert.match(content.text, /Current-application linked-role metadata audit re-verifies pinned identity/u)
  assert.match(content.text, /Current-application SKU audit re-verifies pinned identity/u)
  assert.match(content.text, /Activity-instance inspection binds one opaque ID to pinned identity/u)
  assert.match(content.text, /Application monetization audit requires a separate disabled-by-default capability/u)
  assert.match(content.text, /Subscription reads require exactly one separately configured user/u)
  assert.match(content.text, /entitlements remain authority for access conclusions/u)
})

