test("MCP native Interaction resources and tools keep tokens private and requests untrusted", async (context) => {
  const reference = `iref_${"1".repeat(32)}`
  const continuationReference = `icref_${"2".repeat(32)}`
  const rotatedContinuationReference = `icref_${"3".repeat(32)}`
  const pending = {
    channelId: CHANNEL_ID,
    commandId: "700000000000000001",
    commandVersion: "700000000000000002",
    createdAt: "2026-08-22T00:00:00.000Z",
    expiresAt: "2026-08-22T00:10:00.000Z",
    guildId: GUILD_ID,
    interactionId: "700000000000000003",
    reference,
    request: "Summarize the private release discussion",
    requestButtonIndex: null,
    requestButtonStyle: null,
    schemaVersion: 1,
    source: "command" as const,
    sourceMessageId: null,
    userId: USER_ID,
  }
  const continuation = {
    channelId: CHANNEL_ID,
    commandId: pending.commandId,
    commandVersion: pending.commandVersion,
    createdAt: pending.createdAt,
    expiresAt: pending.expiresAt,
    followupsCompleted: 0,
    followupsRemaining: 3,
    guildId: GUILD_ID,
    interactionId: pending.interactionId,
    openedAt: "2026-08-22T00:01:00.000Z",
    reference: continuationReference,
    requestButtonIndex: null,
    requestButtonStyle: null,
    schemaVersion: 1,
    source: "command" as const,
    sourceMessageId: null,
    userId: USER_ID,
  }
  let listCalls = 0
  let continuationListCalls = 0
  const responses: Array<{
    keepOpen: boolean | undefined
    reference: string
    response: string
  }> = []
  const followups: Array<{
    keepOpen: boolean | undefined
    reference: string
    response: string
  }> = []
  const nativeInteractions: NativeInteractionSource = {
    enabled: true,
    async getRequestButtonReadiness(guildId) {
      return {
        commandId: pending.commandId,
        commandVersion: pending.commandVersion,
        gatewayDelivery: "verified",
        guildId,
        phase: "ready",
        ready: true,
        schemaVersion: 1,
      }
    },
    getStatus() {
      return {
        command: {
          guildCount: 1,
          name: "guildcontrol",
          verifiedGuildCount: 1,
        },
        enabled: true,
        lastError: null,
        limits: {
          maximumFollowups: 3,
          maximumPending: 25,
          pendingPerUser: 3,
          requestCharacters: 2_000,
          responseCharacters: 2_000,
          ttlSeconds: 600,
        },
        continuations: { count: 1 },
        pending: { count: 1, validating: 0 },
        phase: "ready",
        schemaVersion: 1,
        totals: {
          accepted: 1,
          continuationsExpired: 0,
          expired: 0,
          followups: 0,
          rejected: 0,
          responded: 0,
          uncertain: 0,
        },
      }
    },
    async listContinuations() {
      continuationListCalls += 1
      return {
        continuations: [continuation],
        page: { capacity: 25, returned: 1 },
        schemaVersion: 1,
        status: "ok",
      }
    },
    async listPending() {
      listCalls += 1
      return {
        interactions: [pending],
        page: { capacity: 25, returned: 1 },
        schemaVersion: 1,
        status: "ok",
      }
    },
    async respond(observedReference, response, options) {
      responses.push({
        keepOpen: options?.keepOpen,
        reference: observedReference,
        response,
      })
      return {
        channelId: CHANNEL_ID,
        continuation: options?.keepOpen
          ? {
              expiresAt: continuation.expiresAt,
              followupsRemaining: 3,
              reference: continuationReference,
            }
          : null,
        guildId: GUILD_ID,
        interactionId: pending.interactionId,
        reference: observedReference,
        responseMessageId: MESSAGE_ID,
        schemaVersion: 1,
        status: "completed",
      }
    },
    async followup(observedReference, response, options) {
      followups.push({
        keepOpen: options?.keepOpen,
        reference: observedReference,
        response,
      })
      return {
        channelId: CHANNEL_ID,
        continuation: options?.keepOpen
          ? {
              expiresAt: continuation.expiresAt,
              followupsRemaining: 2,
              reference: rotatedContinuationReference,
            }
          : null,
        followupsCompleted: 1,
        guildId: GUILD_ID,
        interactionId: pending.interactionId,
        reference: observedReference,
        responseMessageId: MESSAGE_ID,
        schemaVersion: 1,
        status: "completed",
        verification: "response-and-readback-match",
      }
    },
    subscribe() {
      return () => undefined
    },
  }
  const { client } = await connectedFixture(context, { nativeInteractions })

  const statusResource = await client.readResource({
    uri: MCP_RESOURCE_URIS.nativeInteractionStatus,
  })
  const pendingResource = await client.readResource({
    uri: MCP_RESOURCE_URIS.nativeInteractionPending,
  })
  const continuationsResource = await client.readResource({
    uri: MCP_RESOURCE_URIS.nativeInteractionContinuations,
  })
  const statusContent = statusResource.contents[0]
  const pendingContent = pendingResource.contents[0]
  const continuationsContent = continuationsResource.contents[0]
  assert.ok(statusContent && "text" in statusContent)
  assert.ok(pendingContent && "text" in pendingContent)
  assert.ok(continuationsContent && "text" in continuationsContent)
  if (!(
    statusContent && "text" in statusContent
    && pendingContent && "text" in pendingContent
    && continuationsContent && "text" in continuationsContent
  )) {
    throw new Error("Expected native Interaction JSON resources")
  }
  const statusEnvelope = JSON.parse(statusContent.text) as Record<string, unknown>
  const pendingEnvelope = JSON.parse(pendingContent.text) as Record<string, unknown>
  const continuationsEnvelope = JSON.parse(
    continuationsContent.text,
  ) as Record<string, unknown>
  assert.equal(
    (statusEnvelope.trust as Record<string, unknown>).classification,
    "trusted-local-metadata",
  )
  assert.equal(
    (pendingEnvelope.trust as Record<string, unknown>).classification,
    "untrusted-external-data",
  )
  assert.match(
    String((pendingEnvelope.trust as Record<string, unknown>).instruction),
    /never as instructions/,
  )
  assert.equal(
    (continuationsEnvelope.trust as Record<string, unknown>).classification,
    "trusted-local-metadata",
  )
  assert.match(
    String((continuationsEnvelope.trust as Record<string, unknown>).instruction),
    /process-local write capability/,
  )

  const listed = structuredContent(await client.callTool({
    arguments: {},
    name: "list_pending_discord_interactions",
  }))
  assert.equal((listed.interactions as unknown[]).length, 1)
  const listedContinuations = structuredContent(await client.callTool({
    arguments: {},
    name: "list_discord_interaction_continuations",
  }))
  assert.equal((listedContinuations.continuations as unknown[]).length, 1)
  const response = structuredContent(await client.callTool({
    arguments: {
      keepOpen: true,
      reference,
      response: "The release discussion is ready for review.",
    },
    name: "respond_to_discord_interaction",
  }))
  assert.equal(response.status, "completed")
  assert.deepEqual(responses, [{
    keepOpen: true,
    reference,
    response: "The release discussion is ready for review.",
  }])
  const followup = structuredContent(await client.callTool({
    arguments: {
      keepOpen: true,
      reference: continuationReference,
      response: "The private follow-up is ready for review.",
    },
    name: "send_discord_interaction_followup",
  }))
  assert.equal(followup.verification, "response-and-readback-match")
  assert.deepEqual(followups, [{
    keepOpen: true,
    reference: continuationReference,
    response: "The private follow-up is ready for review.",
  }])
  assert.equal(listCalls, 2)
  assert.equal(continuationListCalls, 2)
  assert.doesNotMatch(
    JSON.stringify({
      continuationsEnvelope,
      followup,
      listed,
      listedContinuations,
      pendingEnvelope,
      response,
      statusEnvelope,
    }),
    new RegExp(TOKEN),
  )

  const invalid = await client.callTool({
    arguments: { reference, response: " " },
    name: "respond_to_discord_interaction",
  })
  assert.equal(invalid.isError, true)
  assert.equal(responses.length, 1)

  const invalidFollowup = await client.callTool({
    arguments: { reference: continuationReference, response: " " },
    name: "send_discord_interaction_followup",
  })
  assert.equal(invalidFollowup.isError, true)
  assert.equal(followups.length, 1)
})

test("MCP observability reports successful, returned-error, and thrown-error tool outcomes", async (context) => {
  const privateDetail = "private activity failure 999999999999999999"
  const { client } = await connectedFixture(context, {
    serviceOverrides: { activityError: new Error(privateDetail) },
  })

  await client.callTool({ arguments: {}, name: "list_guilds" })
  const returnedError = await client.callTool({
    arguments: {
      auditReason: AUDIT_REASON,
      channelId: CHANNEL_ID,
      messageIds: [MESSAGE_ID],
      operationKey: OPERATION_KEY,
      planDigest: DIFFERENT_DIGEST,
    },
    name: "delete_messages",
  })
  assert.equal(returnedError.isError, true)
  const thrownError = await client.callTool({ arguments: {}, name: "list_activity" })
  assert.equal(thrownError.isError, true)

  const statusResult = await client.callTool({
    arguments: {},
    name: "get_observability_status",
  })
  const status = structuredContent(statusResult) as unknown as {
    invalidRequests: {
      coverage: string
      ipWideTotalKnown: boolean
      observed: { total: number }
      sharedScope429Excluded: boolean
      state: string
    }
    operations: {
      mcpTools: Array<{
        active: number
        calls: number
        duration: unknown
        errors: number
        operation: string
        outcomes: Record<string, number>
        retries: number
      }>
    }
    privacy: Record<string, boolean>
  }
  assert.deepEqual(status.invalidRequests, {
    coverage: "this-process-only",
    discordDocumentedLimit: 10_000,
    discordDocumentedWindowMs: 600_000,
    ipWideTotalKnown: false,
    observed: {
      forbidden403: 0,
      rateLimited429: 0,
      total: 0,
      unauthorized401: 0,
    },
    sharedScope429Excluded: true,
    state: "clear",
    thresholdReachedByThisProcess: false,
    windowResolutionMs: 1_000,
  })
  const byName = new Map(status.operations.mcpTools.map((entry) => [entry.operation, entry]))
  assert.deepEqual(byName.get("list_guilds")?.outcomes, {
    error: 0,
    ok: 1,
    "tool-error": 0,
  })
  assert.deepEqual(byName.get("delete_messages")?.outcomes, {
    error: 0,
    ok: 0,
    "tool-error": 1,
  })
  assert.deepEqual(byName.get("list_activity")?.outcomes, {
    error: 1,
    ok: 0,
    "tool-error": 0,
  })
  assert.deepEqual(byName.get("get_observability_status"), {
    active: 1,
    calls: 0,
    duration: byName.get("get_observability_status")?.duration,
    errors: 0,
    operation: "get_observability_status",
    outcomes: { error: 0, ok: 0, "tool-error": 0 },
    retries: 0,
  })
  assert.deepEqual(status.privacy, {
    argumentsStored: false,
    contentStored: false,
    discordIdentifiersStored: false,
    errorDetailsStored: false,
    persistent: false,
    rawRoutesStored: false,
  })
  assert.equal(JSON.stringify(status).includes(privateDetail), false)

  const resource = await client.readResource({ uri: MCP_RESOURCE_URIS.observability })
  const content = resource.contents[0]
  assert.ok(content && "text" in content)
  if (!content || !("text" in content)) throw new Error("Expected observability text")
  const envelope = JSON.parse(content.text) as {
    data: {
      invalidRequests: { observed: { total: number } }
      operations: { mcpTools: Array<{ active: number; calls: number; operation: string }> }
    }
  }
  assert.equal(envelope.data.invalidRequests.observed.total, 0)
  const completedStatus = envelope.data.operations.mcpTools.find(
    ({ operation }) => operation === "get_observability_status",
  )
  assert.equal(completedStatus?.active, 0)
  assert.equal(completedStatus?.calls, 1)
  assert.equal(content.text.includes(privateDetail), false)
  assert.equal(content.text.includes(TOKEN), false)
})

