test("MCP channel metadata execution exposes uncertainty and content-free conflicts", async (context) => {
  const approve = async () => ({
    action: "accept" as const,
    content: { approve: true },
  })
  const argumentsValue = {
    ...channelMetadataRequest(),
    planDigest: DIGEST,
  }
  const uncertain = await connectedFixture(context, {
    elicitationHandler: approve,
    serviceOverrides: {
      channelMetadataError: new ChannelMetadataExecutionError(
        "Discord channel metadata outcome is uncertain",
        {
          activityId: "activity-channel-metadata",
          channelId: CHANNEL_ID,
          guildId: GUILD_ID,
          operationKeyHash: OPERATION_KEY_HASH,
          planDigest: DIGEST,
          schemaVersion: 1,
          status: "uncertain",
        },
      ),
    },
  })
  const uncertainResult = await uncertain.client.callTool({
    arguments: argumentsValue,
    name: "execute_channel_metadata_change",
  })
  assert.equal(structuredContent(uncertainResult).status, "outcome-uncertain")

  const receipt = {
    activityId: "activity-channel-metadata",
    error: null,
    guildId: GUILD_ID,
    operationKeyHash: OPERATION_KEY_HASH,
    resourceId: CHANNEL_ID,
    status: "completed",
    timestamp: "2026-08-21T00:00:00.000Z",
    verification: "match",
  }
  const conflict = await connectedFixture(context, {
    elicitationHandler: approve,
    serviceOverrides: {
      channelMetadataError: new ChannelMetadataOperationConflictError(receipt),
    },
  })
  const conflictResult = await conflict.client.callTool({
    arguments: argumentsValue,
    name: "execute_channel_metadata_change",
  })
  assert.equal(structuredContent(conflictResult).status, "operation-key-conflict")
  assert.deepEqual(
    (structuredContent(conflictResult).error as Record<string, unknown>).receipt,
    receipt,
  )
  assert.doesNotMatch(
    JSON.stringify(conflictResult),
    new RegExp(CHANNEL_METADATA_OPERATION_KEY),
  )

  const claimId = `claim_${"c".repeat(32)}`
  for (const coordination of [
    {
      error: new WriteCoordinationConflictError(claimId),
      status: "coordination-conflict",
    },
    {
      error: new WriteCoordinationQuarantinedError(claimId),
      status: "coordination-quarantined",
    },
  ]) {
    const fixture = await connectedFixture(context, {
      elicitationHandler: approve,
      serviceOverrides: { channelMetadataError: coordination.error },
    })
    const result = await fixture.client.callTool({
      arguments: argumentsValue,
      name: "execute_channel_metadata_change",
    })
    const structured = structuredContent(result)
    assert.equal(structured.status, coordination.status)
    assert.equal(
      (structured.error as Record<string, unknown>).claimId,
      claimId,
    )
    assert.match(JSON.stringify(result), new RegExp(claimId))
  }

  const stateError = await connectedFixture(context, {
    elicitationHandler: approve,
    serviceOverrides: {
      channelMetadataError: new WriteCoordinationStateError(
        "Discord write coordination state is unavailable",
      ),
    },
  })
  const stateResult = await stateError.client.callTool({
    arguments: argumentsValue,
    name: "execute_channel_metadata_change",
  })
  assert.equal(
    structuredContent(stateResult).status,
    "coordination-state-error",
  )
})

test("MCP voice channel status read and plan preserve exact transient intent", async (context) => {
  const { calls, client } = await connectedFixture(context)
  const read = await client.callTool({
    arguments: { channelId: CHANNEL_ID, guildId: GUILD_ID },
    name: "get_voice_channel_status",
  })
  const request = voiceChannelStatusRequest()
  const planned = await client.callTool({
    arguments: { ...request },
    name: "plan_voice_channel_status_change",
  })
  const cleared = await client.callTool({
    arguments: { ...voiceChannelStatusRequest({ status: null }) },
    name: "plan_voice_channel_status_change",
  })
  const exactCodepointLimit = await client.callTool({
    arguments: { ...voiceChannelStatusRequest({ status: "😀".repeat(500) }) },
    name: "plan_voice_channel_status_change",
  })
  const invalid = await Promise.all([
    client.callTool({
      arguments: {
        auditReason: AUDIT_REASON,
        channelId: CHANNEL_ID,
        guildId: GUILD_ID,
        operationKey: VOICE_CHANNEL_STATUS_OPERATION_KEY,
      },
      name: "plan_voice_channel_status_change",
    }),
    client.callTool({
      arguments: { ...voiceChannelStatusRequest({ status: " padded " }) },
      name: "plan_voice_channel_status_change",
    }),
    client.callTool({
      arguments: { ...voiceChannelStatusRequest({ status: "bad\nstatus" }) },
      name: "plan_voice_channel_status_change",
    }),
    client.callTool({
      arguments: { ...voiceChannelStatusRequest({ status: "😀".repeat(501) }) },
      name: "plan_voice_channel_status_change",
    }),
    client.callTool({
      arguments: { ...request, enumerate: true },
      name: "plan_voice_channel_status_change",
    }),
  ])

  const readContent = structuredContent(read)
  assert.equal(
    (readContent.current as Record<string, unknown>).status,
    VOICE_CHANNEL_STATUS_CURRENT,
  )
  assert.equal(
    (readContent.privacy as Record<string, unknown>).statusTextPersisted,
    false,
  )
  assert.equal(structuredContent(planned).desiredStatus, VOICE_CHANNEL_STATUS_DESIRED)
  assert.equal(structuredContent(cleared).desiredStatus, null)
  assert.equal(
    structuredContent(exactCodepointLimit).desiredStatus,
    "😀".repeat(500),
  )
  for (const result of invalid) assert.equal(result.isError, true)
  assert.doesNotMatch(JSON.stringify(planned), new RegExp(VOICE_CHANNEL_STATUS_OPERATION_KEY))
  assert.equal(calls.voiceChannelStatusGet, 1)
  assert.equal(calls.voiceChannelStatusPlan, 3)
})

