test("MCP guild scaffolds expose resumable, uncertain, and content-free conflict outcomes", async (context) => {
  const approve = async () => ({
    action: "accept" as const,
    content: { approve: true },
  })
  const arguments_ = {
    auditReason: AUDIT_REASON,
    channels: [{ key: "review-category", kind: "category", name: "Review" }],
    guildId: GUILD_ID,
    operationKey: GUILD_SCAFFOLD_OPERATION_KEY,
    planDigest: DIGEST,
    roles: [{
      key: "reviewer-role",
      name: "reviewer",
      permissions: ["VIEW_CHANNEL"],
    }],
  }
  const paused = await connectedFixture(context, {
    elicitationHandler: approve,
    serviceOverrides: {
      guildScaffoldError: new GuildScaffoldExecutionError(
        "A scaffold step stopped before write reservation",
        { status: "paused-step-prewrite" },
      ),
    },
  })
  const pausedResult = await paused.client.callTool({
    arguments: arguments_,
    name: "execute_guild_scaffold",
  })
  assert.equal(structuredContent(pausedResult).status, "paused-step-prewrite")

  const uncertain = await connectedFixture(context, {
    elicitationHandler: approve,
    serviceOverrides: {
      guildScaffoldError: new GuildScaffoldExecutionError(
        "A scaffold write outcome is uncertain",
        { status: "uncertain" },
      ),
    },
  })
  const uncertainResult = await uncertain.client.callTool({
    arguments: arguments_,
    name: "execute_guild_scaffold",
  })
  assert.equal(structuredContent(uncertainResult).status, "outcome-uncertain")

  const receipt = {
    activityId: "scaffold-operation",
    error: null,
    guildId: GUILD_ID,
    operationKeyHash: OPERATION_KEY_HASH,
    resourceId: null,
    status: "pending" as const,
    timestamp: "2026-08-20T00:00:00.000Z",
    verification: null,
  }
  const conflict = await connectedFixture(context, {
    elicitationHandler: approve,
    serviceOverrides: {
      guildScaffoldError: new GuildScaffoldOperationConflictError(
        "The scaffold operation is already reserved",
        receipt,
      ),
    },
  })
  const conflictResult = await conflict.client.callTool({
    arguments: arguments_,
    name: "execute_guild_scaffold",
  })
  assert.equal(structuredContent(conflictResult).status, "operation-key-conflict")
  assert.deepEqual(
    (structuredContent(conflictResult).error as Record<string, unknown>).receipt,
    receipt,
  )
  assert.doesNotMatch(
    JSON.stringify(conflictResult),
    new RegExp(GUILD_SCAFFOLD_OPERATION_KEY),
  )

  const unsafeConflict = await connectedFixture(context, {
    elicitationHandler: approve,
    serviceOverrides: {
      guildScaffoldError: new GuildScaffoldOperationConflictError(
        "The scaffold receipt is unsafe",
        { ...receipt, operationKey: GUILD_SCAFFOLD_OPERATION_KEY },
      ),
    },
  })
  const unsafeResult = await unsafeConflict.client.callTool({
    arguments: arguments_,
    name: "execute_guild_scaffold",
  })
  assert.deepEqual(
    (structuredContent(unsafeResult).error as Record<string, unknown>).receipt,
    { status: "unavailable" },
  )
  assert.doesNotMatch(
    JSON.stringify(unsafeResult),
    new RegExp(GUILD_SCAFFOLD_OPERATION_KEY),
  )
})

test("MCP member nickname changes plan exact targets and reject unsafe schemas", async (context) => {
  const { calls, client } = await connectedFixture(context)

  const currentBot = await client.callTool({
    arguments: {
      auditReason: AUDIT_REASON,
      guildId: GUILD_ID,
      nickname: MEMBER_NICKNAME,
      operationKey: MEMBER_NICKNAME_OPERATION_KEY,
      target: { kind: "current-bot" },
    },
    name: "plan_member_nickname_change",
  })
  const exactMember = await client.callTool({
    arguments: {
      auditReason: AUDIT_REASON,
      guildId: GUILD_ID,
      nickname: null,
      operationKey: MEMBER_NICKNAME_OPERATION_KEY,
      target: { kind: "member", userId: USER_ID },
    },
    name: "plan_member_nickname_change",
  })
  const invalidRequests = [
    {
      auditReason: AUDIT_REASON,
      guildId: GUILD_ID,
      nickname: "",
      operationKey: MEMBER_NICKNAME_OPERATION_KEY,
      target: { kind: "current-bot" },
    },
    {
      auditReason: AUDIT_REASON,
      guildId: GUILD_ID,
      nickname: " surrounding ",
      operationKey: MEMBER_NICKNAME_OPERATION_KEY,
      target: { kind: "current-bot" },
    },
    {
      auditReason: AUDIT_REASON,
      guildId: GUILD_ID,
      nickname: "repeated  whitespace",
      operationKey: MEMBER_NICKNAME_OPERATION_KEY,
      target: { kind: "current-bot" },
    },
    {
      auditReason: AUDIT_REASON,
      guildId: GUILD_ID,
      nickname: "\ud800",
      operationKey: MEMBER_NICKNAME_OPERATION_KEY,
      target: { kind: "current-bot" },
    },
    {
      auditReason: AUDIT_REASON,
      guildId: GUILD_ID,
      nickname: "x".repeat(33),
      operationKey: MEMBER_NICKNAME_OPERATION_KEY,
      target: { kind: "current-bot" },
    },
    {
      auditReason: AUDIT_REASON,
      guildId: GUILD_ID,
      nickname: MEMBER_NICKNAME,
      operationKey: MEMBER_NICKNAME_OPERATION_KEY,
      target: { kind: "current-bot", userId: USER_ID },
    },
    {
      auditReason: AUDIT_REASON,
      guildId: GUILD_ID,
      nickname: MEMBER_NICKNAME,
      operationKey: MEMBER_NICKNAME_OPERATION_KEY,
      target: { kind: "member" },
    },
    {
      auditReason: AUDIT_REASON,
      guildId: GUILD_ID,
      nickname: MEMBER_NICKNAME,
      operationKey: MEMBER_NICKNAME_OPERATION_KEY,
      replaceDisplayName: true,
      target: { kind: "member", userId: USER_ID },
    },
  ]
  for (const arguments_ of invalidRequests) {
    const result = await client.callTool({
      arguments: arguments_ as never,
      name: "plan_member_nickname_change",
    })
    assert.equal(result.isError, true)
  }

  assert.equal(structuredContent(currentBot).status, "planned")
  assert.equal(structuredContent(currentBot).desiredNickname, MEMBER_NICKNAME)
  assert.equal(
    (structuredContent(currentBot).target as Record<string, unknown>).kind,
    "current-bot",
  )
  assert.equal(structuredContent(exactMember).desiredNickname, null)
  assert.equal(
    (structuredContent(exactMember).target as Record<string, unknown>).id,
    USER_ID,
  )
  assert.equal(calls.memberNicknamePlan, 2)
})

