test("MCP stdio progressive discovery negotiates modern tool-list changes", async (context) => {
  const configFile = await stdioConfigFile(context, {
    toolsets: ["deletion"],
    toolSurface: "progressive",
  })
  const transport = new StdioClientTransport({
    args: ["--import", "tsx", "src/cli.ts", "serve", "--config", configFile],
    command: process.execPath,
    cwd: process.cwd(),
    env: {
      [STDIO_TOKEN_VARIABLE]: TOKEN,
      PATH: process.env.PATH || "",
    },
    stderr: "pipe",
  })
  let diagnostics = ""
  transport.stderr?.on("data", (chunk) => {
    diagnostics += String(chunk)
  })
  let changedTools: Tool[] | null = null
  let resolveNotification: (() => void) | undefined
  let rejectNotification: ((error: Error) => void) | undefined
  const notification = new Promise<void>((resolve, reject) => {
    resolveNotification = resolve
    rejectNotification = reject
  })
  const client = new Client(
    { name: "guildcontrol-stdio-progressive-test", version: "1.0.0" },
    {
      capabilities: { elicitation: {} },
      listChanged: {
        tools: {
          debounceMs: 0,
          onChanged(error, tools) {
            if (error) {
              rejectNotification?.(error)
              return
            }
            changedTools = tools
            resolveNotification?.()
          },
        },
      },
      versionNegotiation: { mode: { pin: "2026-07-28" } },
    },
  )
  context.after(async () => {
    try {
      await client.close()
    } catch {}
  })

  await client.connect(transport)
  assert.deepEqual(
    (await client.listTools()).tools.map(({ name }) => name),
    [MCP_DISCOVERY_TOOL_NAME, MCP_DOCUMENTATION_SEARCH_TOOL_NAME],
  )
  const discovered = structuredContent(await client.callTool({
    arguments: { query: "plan_message_deletion" },
    name: MCP_DISCOVERY_TOOL_NAME,
  }))
  assert.deepEqual(discovered.newlyEnabledToolNames, [
    "delete_messages",
    "plan_message_deletion",
  ])

  let notificationTimer: NodeJS.Timeout | undefined
  await Promise.race([
    notification,
    new Promise<never>((_resolve, reject) => {
      notificationTimer = setTimeout(
        () => reject(new Error("Timed out waiting for MCP tool-list change")),
        LIST_CHANGED_TIMEOUT_MS,
      )
    }),
  ]).finally(() => {
    if (notificationTimer) clearTimeout(notificationTimer)
  })
  assert.ok(changedTools)
  assert.deepEqual((changedTools as Tool[]).map(({ name }) => name), [
    "plan_message_deletion",
    "delete_messages",
    MCP_DISCOVERY_TOOL_NAME,
    MCP_DOCUMENTATION_SEARCH_TOOL_NAME,
  ])
  assert.deepEqual(
    (await client.listTools()).tools.map(({ name }) => name),
    [
      "plan_message_deletion",
      "delete_messages",
      MCP_DISCOVERY_TOOL_NAME,
      MCP_DOCUMENTATION_SEARCH_TOOL_NAME,
    ],
  )
  assert.match(diagnostics, /stdio server ready/)
  assert.doesNotMatch(diagnostics, new RegExp(TOKEN))
})

test("MCP stdio entrypoint negotiates modern catalogs without stdout noise", async (context) => {
  const configFile = await stdioConfigFile(context, {
    toolsets: MCP_TOOLSET_NAMES,
    toolSurface: "full",
  })
  const transport = new StdioClientTransport({
    args: ["--import", "tsx", "src/cli.ts", "serve", "--config", configFile],
    command: process.execPath,
    cwd: process.cwd(),
    env: {
      [STDIO_TOKEN_VARIABLE]: TOKEN,
      PATH: process.env.PATH || "",
    },
    stderr: "pipe",
  })
  let diagnostics = ""
  transport.stderr?.on("data", (chunk) => {
    diagnostics += String(chunk)
  })
  const client = new Client(
    { name: "guildcontrol-stdio-test", version: "1.0.0" },
    {
      capabilities: { elicitation: {} },
      versionNegotiation: { mode: { pin: "2026-07-28" } },
    },
  )
  context.after(async () => {
    try {
      await client.close()
    } catch {}
  })

  await client.connect(transport)
  assert.ok(client.getInstructions()?.startsWith(`${MCP_OPERATIONAL_INSTRUCTION_PREAMBLE} `))
  const [tools, prompts, resources, templates, safety, planReviewApp] = await Promise.all([
    client.listTools(),
    client.listPrompts(),
    client.listResources(),
    client.listResourceTemplates(),
    client.readResource({ uri: "discord://connector/safety" }),
    client.readResource({ uri: MCP_PLAN_REVIEW_APP_URI }),
  ])
  const [guildCompletion, channelCompletion] = await Promise.all([
    client.complete({
      argument: { name: "guildId", value: "100" },
      ref: {
        type: "ref/resource",
        uri: MCP_RESOURCE_TEMPLATE_URIS.guildChannels,
      },
    }),
    client.complete({
      argument: { name: "channelId", value: "200" },
      ref: {
        name: MCP_PROMPT_NAMES.summarizeChannel,
        type: "ref/prompt",
      },
    }),
  ])

  assert.equal(
    tools.tools.length,
    Object.keys(MCP_TOOL_CATALOG).length + MCP_ALWAYS_AVAILABLE_TOOL_NAMES.length,
  )
  assert.equal(prompts.prompts.length, Object.keys(MCP_PROMPT_NAMES).length)
  assert.equal(resources.resources.length, Object.keys(MCP_RESOURCE_URIS).length)
  assert.equal(
    templates.resourceTemplates.length,
    Object.keys(MCP_RESOURCE_TEMPLATE_NAMES).length,
  )
  for (const catalog of [tools, prompts, resources, templates]) {
    assert.equal(catalog.cacheScope, "public")
    assert.equal(catalog.ttlMs, CATALOG_CACHE_TTL_MS)
  }
  assert.equal(safety.cacheScope, "public")
  assert.equal(safety.ttlMs, STATIC_RESOURCE_CACHE_TTL_MS)
  assert.equal(planReviewApp.cacheScope, "public")
  assert.equal(planReviewApp.ttlMs, STATIC_RESOURCE_CACHE_TTL_MS)
  assert.deepEqual(planReviewApp.contents, [{
    _meta: MCP_PLAN_REVIEW_APP_RESOURCE_META,
    mimeType: MCP_PLAN_REVIEW_APP_MIME_TYPE,
    text: MCP_PLAN_REVIEW_APP_HTML,
    uri: MCP_PLAN_REVIEW_APP_URI,
  }])
  assert.deepEqual(
    resources.resources.find(({ uri }) => uri === MCP_PLAN_REVIEW_APP_URI)?._meta,
    MCP_PLAN_REVIEW_APP_RESOURCE_META,
  )
  assert.deepEqual(
    listedTool(tools.tools, "plan_message_deletion")._meta,
    MCP_PLAN_REVIEW_TOOL_META,
  )
  assert.deepEqual(
    client.getServerCapabilities()?.extensions?.[MCP_APP_EXTENSION_ID],
    { mimeTypes: [MCP_PLAN_REVIEW_APP_MIME_TYPE] },
  )
  assert.deepEqual(guildCompletion.completion.values, [GUILD_ID])
  assert.deepEqual(channelCompletion.completion.values, [CHANNEL_ID])
  assert.deepEqual(client.getServerCapabilities()?.completions, {})
  assert.match(diagnostics, /stdio server ready/)
  assert.doesNotMatch(diagnostics, new RegExp(TOKEN))
})

