test("MCP stdio runner starts native Interaction ingress before Gateway and stops it after", async () => {
  const feed = new GatewayEventStore({
    allowedChannelIds: new Set([CHANNEL_ID]),
    allowedGuildIds: new Set([GUILD_ID]),
    cursorNamespace: "nativeinteractionrunner",
    enabled: true,
    eventFeedEnabled: false,
    layoutGuildIds: new Set(),
  })
  const lifecycle: string[] = []
  let releasePreflight: (() => void) | undefined
  const preflight = new Promise<void>((resolve) => {
    releasePreflight = resolve
  })
  const nativeInteractionRuntime: NativeInteractionRuntime = {
    enabled: true,
    async getRequestButtonReadiness(guildId) {
      return {
        commandId: "700000000000000001",
        commandVersion: "700000000000000002",
        gatewayDelivery: "verified",
        guildId,
        phase: "ready",
        ready: true,
        schemaVersion: 1,
      }
    },
    getStatus() {
      return {
        command: {
          guildCount: 1,
          name: "guildcontrol",
          verifiedGuildCount: 1,
        },
        enabled: true,
        lastError: null,
        limits: {
          maximumFollowups: 3,
          maximumPending: 25,
          pendingPerUser: 3,
          requestCharacters: 2_000,
          responseCharacters: 2_000,
          ttlSeconds: 600,
        },
        continuations: { count: 0 },
        pending: { count: 0, validating: 0 },
        phase: "ready",
        schemaVersion: 1,
        totals: {
          accepted: 0,
          continuationsExpired: 0,
          expired: 0,
          followups: 0,
          rejected: 0,
          responded: 0,
          uncertain: 0,
        },
      }
    },
    ingestInteraction() {},
    async listContinuations() {
      return {
        continuations: [],
        page: { capacity: 25, returned: 0 },
        schemaVersion: 1,
        status: "ok",
      }
    },
    async listPending() {
      return {
        interactions: [],
        page: { capacity: 25, returned: 0 },
        schemaVersion: 1,
        status: "ok",
      }
    },
    async respond() {
      throw new Error("No pending native Interaction")
    },
    async followup() {
      throw new Error("No native Interaction continuation")
    },
    async start() {
      lifecycle.push("native-start")
      await preflight
    },
    async stop() {
      lifecycle.push("native-stop")
    },
    subscribe() {
      return () => undefined
    },
  }
  const gatewayRuntime: NonNullable<GuildControlRunOptions["gatewayRuntime"]> = {
    enabled: true,
    layoutEnabled: feed.layoutEnabled,
    soundboardPlaybackEventsEnabled: false,
    getChannelLayout: (guildId) => feed.getChannelLayout(guildId),
    getChannelLayoutStatus: () => feed.getChannelLayoutStatus(),
    getStatus: () => feed.getStatus(),
    listEvents: (options) => feed.listEvents(options),
    async getVoiceChannelStatus() {
      throw new Error("Voice channel status evidence is disabled")
    },
    async start() {
      lifecycle.push("gateway-start")
    },
    async stop() {
      lifecycle.push("gateway-stop")
    },
    subscribe: (listener) => feed.subscribe(listener),
    subscribeChannelLayouts: (listener) => feed.subscribeChannelLayouts(listener),
    async waitForSoundboardPlaybackEvent() {
      throw new Error("Soundboard playback events are disabled")
    },
    async waitForVoiceChannelStatusUpdate() {
      throw new Error("Voice channel status evidence is disabled")
    },
    voiceChannelStatusEnabled: false,
  }
  const serviceData = serviceFixture()
  const configOverrides = {
    token: TOKEN,
    capabilities: {
      nativeInteractions: true,
    },
    identity: {
      applicationId: APPLICATION_ID,
      botId: BOT_ID,
    },
    readScope: {
      channelIds: [CHANNEL_ID],
      guildIds: [GUILD_ID],
    },
    scopes: {
      nativeInteractionChannelIds: [CHANNEL_ID],
      nativeInteractionGuildIds: [GUILD_ID],
      nativeInteractionUserIds: [USER_ID],
    },
  }
  const handle = runGuildControlServer({
    config: loadFixtureConfig(configOverrides),
    environment: { DISCORD_BOT_TOKEN: TOKEN },
    gatewayRuntime,
    nativeInteractionRuntime,
    service: serviceData.service,
    stderr: { write: () => true },
    stdin: new PassThrough(),
    stdout: new PassThrough(),
  })

  assert.deepEqual(lifecycle, ["native-start"])
  releasePreflight?.()
  await settleNotifications()
  assert.deepEqual(lifecycle, ["native-start", "gateway-start"])
  await handle.close()
  assert.deepEqual(lifecycle, [
    "native-start",
    "gateway-start",
    "gateway-stop",
    "native-stop",
  ])
})

test("MCP stdio runner stops Gateway and observability runtimes idempotently", async () => {
  const feed = new GatewayEventStore({
    allowedChannelIds: new Set([CHANNEL_ID]),
    allowedGuildIds: new Set([GUILD_ID]),
    cursorNamespace: "runnergateway",
    enabled: true,
    eventFeedEnabled: false,
    layoutGuildIds: new Set(),
  })
  let starts = 0
  let stops = 0
  let reportStopped: (() => void) | undefined
  const stopped = new Promise<void>((resolve) => {
    reportStopped = resolve
  })
  const gatewayRuntime: NonNullable<GuildControlRunOptions["gatewayRuntime"]> = {
    enabled: true,
    layoutEnabled: feed.layoutEnabled,
    soundboardPlaybackEventsEnabled: false,
    getChannelLayout: (guildId) => feed.getChannelLayout(guildId),
    getChannelLayoutStatus: () => feed.getChannelLayoutStatus(),
    getStatus: () => feed.getStatus(),
    listEvents: (options) => feed.listEvents(options),
    async getVoiceChannelStatus() {
      throw new Error("Voice channel status evidence is disabled")
    },
    async start() {
      starts += 1
    },
    async stop() {
      stops += 1
      reportStopped?.()
    },
    subscribe: (listener) => feed.subscribe(listener),
    subscribeChannelLayouts: (listener) => feed.subscribeChannelLayouts(listener),
    async waitForSoundboardPlaybackEvent() {
      throw new Error("Soundboard playback events are disabled")
    },
    async waitForVoiceChannelStatusUpdate() {
      throw new Error("Voice channel status evidence is disabled")
    },
    voiceChannelStatusEnabled: false,
  }
  let flushes = 0
  let telemetryStops = 0
  const observabilityRuntime = new OperationalTelemetry({
    config: loadObservabilityDocumentConfig({ exportEnabled: true }, {}, [TOKEN]),
    otlpFactory(_config, sink) {
      sink.transitionExporter("running")
      return {
        async forceFlush() {
          flushes += 1
        },
        async shutdown() {
          telemetryStops += 1
          sink.transitionExporter("stopped")
        },
      }
    },
  })
  let diagnostics = ""
  const stdin = new PassThrough()
  const stdout = new PassThrough()
  const handle = runGuildControlServer({
    config: loadFixtureConfig({
      token: TOKEN,
    }),
    environment: {
      DISCORD_BOT_TOKEN: TOKEN,
    },
    gatewayRuntime,
    stdin,
    observabilityRuntime,
    stderr: {
      write(value) {
        diagnostics += String(value)
        return true
      },
    },
    stdout,
  })

  assert.equal(starts, 1)
  assert.equal(observabilityRuntime.getObservabilityStatus().exporter.state, "running")
  assert.match(diagnostics, /stdio server ready/)
  stdin.end()
  await stopped
  await handle.close()
  assert.equal(stops, 1)
  assert.equal(flushes, 1)
  assert.equal(telemetryStops, 1)
  assert.equal(observabilityRuntime.getObservabilityStatus().exporter.state, "stopped")
})
